JOBS_JSON
JSHA=$(sha256sum "$VAR/jobs.json" | cut -c1-12)
say "PREREG locked jobs.json sha256=$JSHA -- scrolls, prediction stores, seed banks (support-gated on m7 sheet voxels), GEN=$GEN MIN_AREA=$MIN_AREA TIMEOUT=${TIMEOUT_S}s; alignment gate (<30 deg to the local lamellae) runs LOCALLY after fetch; nothing here is a surface claim"

CURRENT_STAGE=boot
fail_linger() { touch "$OUT/FAILED"; echo FAILED > "$VAR/stage"; say "FAILED -- run is dead; terminate the pod after reading"; [ "$LINGER_EXIT" = 1 ] && exit 1; while :; do sleep 300; say "FAILED (lingering)"; done; }
die() { say "FATAL stage=$CURRENT_STAGE $*"; fail_linger; }
trap 'ec=$?; say "FATAL stage=$CURRENT_STAGE exit=$ec line=${BASH_LINENO[0]} cmd: ${BASH_COMMAND}"; fail_linger' ERR
stage_open() { CURRENT_STAGE=$1; echo "$1" > "$VAR/stage"; STAGE_T0=$SECONDS; say "=== STAGE $1 OPEN ==="; }
stage_close() { touch "$VAR/done_$1"; say "=== STAGE $1 DONE ($((SECONDS - STAGE_T0))s) ==="; }
stage_done() { [ -f "$VAR/done_$1" ]; }
retry() { local tries=$1; shift; local n=1 waits=(0 10 30 90); while :; do if "$@"; then return 0; fi; [ $n -ge "$tries" ] && return 1; say "retry $n/$tries failed: $1"; sleep "${waits[$n]}"; n=$((n+1)); done; }

if [ "$DRY" = 1 ]; then
  for st in tracer grow_all bundle; do stage_open "$st"; sleep 0.2; stage_close "$st"; done
  say "ALL DONE (DRY)"; echo IDLE > "$VAR/stage"; [ "$LINGER_EXIT" = 1 ] && exit 0; while :; do sleep 300; say "IDLE (DRY)"; done
fi

# ---- tracer: release tarball first, build from main as fallback --------------
stage_open tracer
export DEBIAN_FRONTEND=noninteractive
apt-get update -qq >/dev/null 2>&1 || true
apt-get install -y -qq curl jq >/dev/null 2>&1 || true
BIN=""
if retry 3 curl -fsSL --max-time 900 -o "$WORK/vc_bin.tgz" "$VC_BIN_URL"; then
  SZ=$(stat -c %s "$WORK/vc_bin.tgz")
  if [ "$SZ" = "$VC_BIN_BYTES" ]; then
    mkdir -p "$WORK/binpack" && tar xzf "$WORK/vc_bin.tgz" -C "$WORK/binpack"
    CAND=$(find "$WORK/binpack" -maxdepth 1 -name vc_grow_seg_from_seed -type f | head -1)
    if [ -n "$CAND" ] && LD_LIBRARY_PATH="$WORK/binpack/lib" "$CAND" --help >/dev/null 2>&1; then
      BIN=$CAND; export LD_LIBRARY_PATH="$WORK/binpack/lib"
      say "tracer: release binary OK ($(cat "$WORK/binpack/BUILT_FROM.txt" 2>/dev/null || echo de3c2494))"
    else
      say "tracer: release binary does not run here ($(LD_LIBRARY_PATH="$WORK/binpack/lib" "$CAND" --help 2>&1 | tail -1 | cut -c1-120)) -- building from main"
    fi
  else
    say "tracer: tarball size $SZ != $VC_BIN_BYTES -- building from main"
  fi
else
  say "tracer: release download failed -- building from main"
fi
if [ -z "$BIN" ]; then
  apt-get install -y -qq git cmake >/dev/null 2>&1 || true
  retry 3 timeout 600 git clone --depth 1 https://github.com/ScrollPrize/villa /villa >> "$OUT/logs/build.log" 2>&1 || die "villa clone failed"
  say "tracer: building vc_grow_seg_from_seed from villa @ $(git -C /villa rev-parse --short HEAD)"
  cmake -S /villa/volume-cartographer -B /build -DCMAKE_BUILD_TYPE=Release >> "$OUT/logs/build.log" 2>&1 || die "cmake configure failed (logs/build.log)"
  cmake --build /build --target vc_grow_seg_from_seed -j"$(nproc)" >> "$OUT/logs/build.log" 2>&1 || die "build failed (logs/build.log)"
  BIN=$(find /build -name vc_grow_seg_from_seed -type f | head -1)
  [ -n "$BIN" ] || die "no binary after build"
  "$BIN" --help >/dev/null 2>&1 || die "built binary does not run"
  say "tracer: built OK"
fi
echo "$BIN" > "$VAR/bin.txt"
stage_close tracer

# ---- grow: per scroll, seeds in waves of WAVE parallel single-threaded tracers
[ "$WAVE" -gt 0 ] || WAVE=$(nproc)
stage_open grow_all
N_SCROLLS=$(jq '.jobs | length' "$VAR/jobs.json")
for ((j = 0; j < N_SCROLLS; j++)); do
  SCROLL=$(jq -r ".jobs[$j].scroll" "$VAR/jobs.json")
  PREDBASE=$(jq -r ".jobs[$j].pred" "$VAR/jobs.json")
  NSEED=$(jq ".jobs[$j].seeds | length" "$VAR/jobs.json")
  ID=${SCROLL#PHerc}
  PD=$WORK/paths_$ID; mkdir -p "$PD" "$WORK/cache_$ID" "$WORK/ngrid_$ID"
  printf '{"url":"%s/%s/representations/predictions/surfaces/%s.normal-grids"}' "$BUCKET" "$SCROLL" "$PREDBASE" > "$WORK/ngrid_$ID/normal-grids-remote.json"
  cat > "$WORK/params_$ID.json" <<EOF
{"mode": "seed", "generations": $GEN, "min_area_cm": $MIN_AREA, "thread_limit": 1, "use_cuda": false,
 "voxelsize": 9.362, "cache_size": 4000000000, "cache_root": "$WORK/cache_$ID", "normal_grid_path": "$WORK/ngrid_$ID"}
EOF
  say "grow $SCROLL: $NSEED seeds, waves of $WAVE, gen=$GEN min_area=$MIN_AREA, store $PREDBASE"
  echo "grow_$ID" > "$VAR/stage"
  for ((i = 0; i < NSEED; i += WAVE)); do
    PIDS=()
    for ((k = i; k < i + WAVE && k < NSEED; k++)); do
      X=$(jq -r ".jobs[$j].seeds[$k].x" "$VAR/jobs.json"); Y=$(jq -r ".jobs[$j].seeds[$k].y" "$VAR/jobs.json"); Z=$(jq -r ".jobs[$j].seeds[$k].z" "$VAR/jobs.json")
      ( timeout "$TIMEOUT_S" "$BIN" --volume "$BUCKET/$SCROLL/representations/predictions/surfaces/$PREDBASE.zarr" \
          --target-dir "$PD" --params "$WORK/params_$ID.json" --seed "$X" "$Y" "$Z" > "$OUT/logs/G_${ID}_$(printf %02d $k).log" 2>&1; \
        echo "G_${ID}_${k}_EXIT=$?" >> "$OUT/logs/G_${ID}_$(printf %02d $k).log" ) &
      PIDS+=($!); sleep 2
    done
    wait "${PIDS[@]}" || true
    say "grow $SCROLL: wave $((i / WAVE + 1)) done; patches so far $(ls "$PD" | grep -c auto_grown || true)"
  done
  say "grow $SCROLL: finished -- $(ls "$PD" | grep -c auto_grown || true) patches from $NSEED seeds; exits: $(grep -h "_EXIT=" "$OUT"/logs/G_${ID}_*.log | sort | uniq -c | tr '\n' ' ')"
done
stage_close grow_all

# ---- bundle: meshes (x/y/z/generations tif + meta) + logs + jobs -------------
stage_open bundle
( cd "$WORK" && tar czf "$OUT/bundle.tgz.part" paths_* -C "$OUT" logs -C "$VAR" jobs.json bin.txt ) || die "bundle tar failed"
mv -f "$OUT/bundle.tgz.part" "$OUT/bundle.tgz"
"$PYTHON_BIN" - "$WORK" "$OUT" <<'PY' || true
import json, os, sys
work, out = sys.argv[1], sys.argv[2]
res = {}
for d in sorted(os.listdir(work)):
    if not d.startswith("paths_"): continue
    ps = []
    for m in sorted(os.listdir(os.path.join(work, d))):
        mp = os.path.join(work, d, m, "meta.json")
        if os.path.exists(mp):
            j = json.load(open(mp)); ps.append({"name": m, "area_cm2": j.get("area_cm2"), "bbox": j.get("bbox")})
    res[d] = ps
json.dump(res, open(os.path.join(out, "results.json"), "w"), indent=1)
for d, ps in res.items():
    print(f"SUMMARY {d}: {len(ps)} patches, areas " + ", ".join(f"{p['area_cm2']:.2f}" for p in ps if p['area_cm2'] is not None))
PY
say "bundle: $OUT/bundle.tgz ($(du -h "$OUT/bundle.tgz" | cut -f1))"
stage_close bundle
say "ALL DONE -- bundle.tgz + results.json served on :$PORT; the laptop guard harvests and TERMINATES. Alignment gate runs locally."
echo IDLE > "$VAR/stage"
[ "$LINGER_EXIT" = 1 ] && exit 0
while :; do sleep 300; say "IDLE -- ALL DONE; terminate the pod"; done
